// WASM module loader for nodebox-electron.
// Initializes eagerly on import. Call functions only after isWasmReady() returns true.

// @ts-expect-error WASM module generated by wasm-pack
import init, { text_to_path, evaluate_library } from '@wasm/nodebox_electron.js';

let ready = false;
let readyCallbacks: (() => void)[] = [];

init().then(() => {
  ready = true;
  for (const cb of readyCallbacks) cb();
  readyCallbacks = [];
});

export function isWasmReady(): boolean {
  return ready;
}

export function onWasmReady(cb: () => void): void {
  if (ready) cb();
  else readyCallbacks.push(cb);
}

export function textToPathSync(
  text: string,
  fontSize: number,
  positionX: number,
  positionY: number,
): string {
  return text_to_path(text, fontSize, positionX, positionY);
}

export function evaluateLibrary(libraryJson: string, frame: number): string {
  return evaluate_library(libraryJson, frame);
}
